import{_ as i,l as s,o as e,c as l,v as r,p as E,x as t,d,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"并发之前：共享可变","description":"","frontmatter":{"title":"并发之前：共享可变","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/shared-mutable-preview.md","filePath":"cs/shared-mutable-preview.md","lastUpdated":1789023840000}'),c={name:"cs/shared-mutable-preview.md"};function A(h,a,B,m,_,u){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="并发之前-共享可变" tabindex="-1">并发之前：共享可变 <a class="header-anchor" href="#并发之前-共享可变" aria-label="Permalink to &quot;并发之前：共享可变&quot;">​</a></h1><div class="epigraph"><p>两个活着的指针指向同一可变对象时，不变量必须对每一次写入同时成立；线程只是把这个事实变成交错执行。</p><footer>—— 据 Kernighan &amp; Ritchie, The C Programming Language, 2nd ed.；ISO/IEC 9899；Bryant and O&#39;Hallaron, Computer Systems: A Programmer&#39;s Perspective 整理</footer></div><p>上一课<a href="/cs/raii">资源获取即初始化</a>要求每个资源同一时刻只有一个主人。本课不重讲销毁，也不从锁与内存模型另起。缺口是：别名课已经允许两个指针指向同一对象，封装要求只通过公开函数写——<strong>若两个调用方同时拿着可变视图，不变量在两次调用之间对谁成立</strong>。这是并发的前置，本身还没有线程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单线程里，共享可变已经能打破不变量：<code>foo_append(a, x)</code> 进行到一半时，若回调或函数指针再次进入 <code>foo_*</code>，对象处于半更新。可重入与否是接口性质。缺口因此不是「以后有多核」，而是<strong>可变共享本身要求临界区</strong>，哪怕临界区用「禁止回调再入」来实现。线程会把交错变得频繁，但不创造这个问题。</p><p>多个名字只读同一对象可以安全共享，只要没有人写，或写入与所有读取互斥。上一课的唯一主人是写方向的答案：要写，先成为唯一可变视图。只读别名可以很多。本课把这条说清，以免后课操作系统把一切归咎于线程。</p><h3 id="共享可变不是「全局变量的别名」" tabindex="-1">共享可变不是「全局变量的别名」 <a class="header-anchor" href="#共享可变不是「全局变量的别名」" aria-label="Permalink to &quot;共享可变不是「全局变量的别名」&quot;">​</a></h3><p>全局只是共享的一种实现。堆上对象交给两个数据结构各存一个指针，同样是共享可变。静态存储只是寿命长。把问题缩小成「少用全局」，会漏掉图、缓存、回调上下文里的别名。相反，全局只读表可以是合法共享。关键是可变，不是存储期。</p><p><span class="marginnote">ISO C11 起，数据竞争是未定义行为；本课尚未引入线程，先在单线程把别名与再入说清。CSAPP 用并发章节说明共享数据需要同步；本课只取它对「共享」的诊断，不把锁实现展开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计接口时声明：对象是否允许重叠的可变引用；回调期间对象处于哪条不变量；哪些函数可重入。需要共享时，把可变集中在一个模块，其它人只持只读指针或不持指针而持标识符。复制是消除共享的方法：代价是一致性要另做。RAII 的唯一主人与本课一致：转移所有权等于转移唯一可变视图。</p>',11)),(e(),E(p,null,{default:t(()=>[n(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RO%5B%22%E5%8F%AA%E8%AF%BB%E5%88%AB%E5%90%8D%E5%8F%AF%E4%BB%A5%E5%BE%88%E5%A4%9A%22%5D%20--%3E%20SAFE%5B%22%E6%97%A0%E5%86%99%E5%88%99%E4%B8%8D%E5%8F%98%E9%87%8F%E7%A8%B3%E5%AE%9A%22%5D%0A%20%20W1%5B%22%E5%8F%AF%E5%8F%98%E8%A7%86%E5%9B%BE%E5%BF%85%E9%A1%BB%E5%94%AF%E4%B8%80%22%5D%20--%3E%20INV%5B%22%E5%86%99%E5%85%A5%E6%9C%9F%E9%97%B4%E4%B8%8D%E5%8F%98%E9%87%8F%E7%94%B1%E8%AF%A5%E5%85%A5%E5%8F%A3%E7%BB%B4%E6%8C%81%22%5D%0A%20%20TWO%5B%22%E4%B8%A4%E4%B8%AA%E5%8F%AF%E5%8F%98%E8%A7%86%E5%9B%BE%22%5D%20--%3E%20RACE%5B%22%E4%BA%A4%E9%94%99%E6%88%96%E5%86%8D%E5%85%A5%E5%8F%AF%E6%89%93%E7%A0%B4%E4%B8%8D%E5%8F%98%E9%87%8F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>单线程再入：函数执行中又调用同一对象的修改入口。解决方案是禁止、或把状态做成可重入（不依赖跨调用的静态缓冲）。后课线程会把「再入」换成「并行」，同步原语才出现。</p><p>只读共享要求写入侧先结束，再发布只读视图——单线程里这是调用顺序，多线程里需要发布的内存序，本课不展开后者。复制消除共享时，要声明复制后两份对象是否还一起维持某个全局不变量（缓存与源数据）。若仍要维持，共享其实没消掉，只是换了协议。文档里写「非线程安全」却允许回调再入，是在说谎。后课工具链不再谈对象模型，但调试器观察到的撕裂写入，根子仍是本课的两个可变视图。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不变量是对存储的全局性质，不知道你从哪个指针进来。两个可变入口等于两条可以交错的状态机。单线程用调用栈保证一次只有一条入口在跑——除非回调把第二条打开。因此「共享可变 + 回调」已经是并发课的玩具模型。后课原子与锁要保护的，正是本课指出的那块存储，而不是「线程对象」本身。</p><p>图形界面回调、信号处理器（异步，后课再谈）、虚表里用户提供的 <code>draw</code>，都是单线程再入的入口。若 <code>draw</code> 里又去改正在遍历的容器，不变量在「遍历进行中」被打破，崩溃可以完全没有线程。解决可以是：文档禁止再入、拷贝一份再遍历、或把更新延后到当前公开调用结束。后课真正的并发只是把「回调」换成「另一个栈上的调用」，需要锁或不可变共享。本课先把可变视图的数目当成接口的一部分写下来。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入互斥量、不讲内存序、不写数据竞争的形式定义。下一课改讲工具链，从<a href="/cs/preprocessor-preview">预处理器</a>回到源文本如何变成编译单元。后课默认：可变共享需要唯一写入口或显式临界区；只读共享可以；回调再入必须在契约里声明。</p><p>唯一可变视图可以按时间交替：A 用完再交给 B，这是所有权转移而不是同时共享。真正的同时共享必须有临界区或改为只读。后课锁保护的就是本课指出的那块存储，不是线程对象本身。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共享可变在单线程就能打破不变量；线程只是放大交错。</li><li>只读别名可多；可变视图应当唯一或进入临界区。</li><li>回调再入是并发的预演。</li><li>下一课回到源文件被真正编译之前的文本替换。</li><li>出处：K&amp;R 对静态缓冲与可重入的提醒；ISO C；CSAPP 对共享数据的诊断。</li></ul>',10))])}const P=i(c,[["render",A]]);export{F as __pageData,P as default};
